    68  otError otThreadSetExtendedPanId(otInstance *aInstance, const otExtendedPanId *aExtendedPanId)
    69  {
    70      otError           error    = OT_ERROR_NONE;
    71      Instance &        instance = *static_cast<Instance *>(aInstance);
    72      otMeshLocalPrefix prefix;
    73
    74      VerifyOrExit(instance.Get<Mle::MleRouter>().GetRole() == OT_DEVICE_ROLE_DISABLED, error = OT_ERROR_INVALID_STATE);
    75
    76      instance.Get<Mac::Mac>().SetExtendedPanId(*static_cast<const Mac::ExtendedPanId *>(aExtendedPanId));
    77
    78      prefix.m8[0] = 0xfd;
    79      memcpy(&prefix.m8[1], aExtendedPanId->m8, 5);
    80      prefix.m8[6] = 0x00;
    81      prefix.m8[7] = 0x00;
    82      instance.Get<Mle::MleRouter>().SetMeshLocalPrefix(prefix);
    83
    84      instance.Get<MeshCoP::ActiveDataset>().Clear();
    85      instance.Get<MeshCoP::PendingDataset>().Clear();
    86
    87  exit:
    88      return error;
    89  }
